head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");
scwin.gSDate;
scwin.gEDate;
scwin.gSTimer;
scwin.gETimer;
scwin.gFirstPacket = true;
scwin.gDtsSizePerRow = 0;
scwin.gDtsSize = 0;
scwin.gDtsFormVerDuringTransaction = false;
scwin.vScrenID = 'ULDSTF25007.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/***********************************************************************
 * - 2018.03.28 수정                                                                                             *
 * if (getObjectValue(txb_form_cd) != "") {fn_GetVersion();}                                *
 * 주석 처리 - 검색 조건 변경 시 fn_GetVersion() 호출 X  (조회 클릭 시 호출)  *
 ************************************************************************/

// gForm loadcompleted 시 수행
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_mkt_id, js_market);
    if (js_market == "3") {
        $c.stf.setObjectValue(rdo_mkt_id, "9");
    } // 20140318  파생상품은 전체 조회되게 기능 추가

    $c.stf.setObjectValue(cmb_dep_cd, js_dep_cd);
    $c.stf.setObjectValue(cmb_emp_no, js_emp_no);
    $c.stf.setObjectValue(cmb_periodTp, "3");
};



//Grid 버전 체크해서 엑셀저장시 gridtoExcel or gridtoOffice 구분
scwin.compareVersion = function(grid) {
    var result = false;
    var verA = grid.Version.split(',');
    var verB = "2,0,1,326".split(','); //기준버전 입력

    var length = (verA.length > verB.length) ? verA.length : verB.length;
    for (var i = 0; i < length; i++) {
        var a = verA[i] ? parseInt(verA[i], 10) : 0;
        var b = verB[i] ? parseInt(verB[i], 10) : 0;
        if (a > b) {
            result = true;
            break;
        }
        if (i == length - 1 && a == b) {
            result = true;
            break;
        }
    }
    return result;
};



// process wait state 함수 - numberMillis 수치만큼 wait.
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};



// 화면 UI 로그 삭제 함수 (개발시에만 로그조회를 위해  txaMain textarea 컴포넌트를 추가하여 사용.)
scwin.ClearLog = function() {
    //txaMain.Text = "";

};

// 화면 UI 로그 조회 함수 (개발시에만 로그조회를 위해  txaMain textarea 컴포넌트를 추가하여 사용.)
scwin.SetLog = function(vtitle, vcontent) {
    //txaMain.Text += "★ SetLog() : "+vtitle+"\n"+vcontent+"\n";

};

// ▼ component resize 시작부(화면크기 변경시 그리드, 조회버튼의 위치및 크기변경)

	//----W-Craft WebSquare 변환 확인: SetEvent----//
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.OnSized = function(winID) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;

	//----W-Craft WebSquare 변환 확인: Provider----//
    scwin.GauceObjResize(frame.Provider("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {

	//----W-Craft WebSquare 변환 확인: WinActive----//

	//----W-Craft WebSquare 변환 확인: Provider----//
        frame.Provider("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }

	//----W-Craft WebSquare 변환 확인: setInterval----//
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);

	//----W-Craft WebSquare 변환 확인: Provider----//
            scwin.gOldWidthSize = frame.Provider("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    var gw = (a - parseInt(grd_main.style.width) - 50);
    grd_item.ReDraw = "false";
    grd_item.style.width = parseInt(grd_item.style.width) + gw; // 상단그리드
    grd_item.ReDraw = "true";
    image_11.style.left = parseInt(image_11.style.left.replace("px", "")) + gw; // 상단패널이미지바
    btn_search.style.left = parseInt(btn_search.style.left.replace("px", "")) + gw; // 상단검색버튼

	//----W-Craft WebSquare 변환 확인: all----//
    var pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "pnl_main");
    pnl_main_grp.style.width = parseInt(pnl_main_grp.style.width.replace("px", "")) + gw; // 상단패널
    grd_main.ReDraw = "false";
    grd_main.style.width = parseInt(grd_main.style.width) + gw; // 하단그리드
    grd_main.ReDraw = "true";
    pnl_content.style.width = parseInt(pnl_content.style.width.replace("px", "")) + gw; // 하단컨텐트패널
    btn_excel.style.left = parseInt(btn_excel.style.left.replace("px", "")) + gw; // 하단엑셀버튼
    scwin.gOldWidthSize = frame.width;
};

// ▲ component resize 종료부(화면크기 변경시 그리드, 조회버튼의 위치및 크기변경)

// 로딩이미지 보이기
scwin.ShowWin2 = function(sval) {

	//----W-Craft WebSquare 변환 확인: Provider----//
    if (frame.Provider("NoData") != null) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//

	//----W-Craft WebSquare 변환 확인: Provider----//
        frame.Provider("NoData").CloseFrame();
    }

	//----W-Craft WebSquare 변환 확인: Provider----//
    if (frame.Provider("LoadingImg2") != null) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//

	//----W-Craft WebSquare 변환 확인: Provider----//
        frame.Provider("LoadingImg2").CloseFrame();
    }
    var tem1 = sval.style.width;
    var temLeft = sval.style.left;
    var temTop = sval.style.top;
    var tem2 = sval.style.height;
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = (eval(tem1 / 2) - 65) + Number(temLeft);
    vYpos = (eval(tem2 / 2) - 18) + Number(temTop);

	//----W-Craft WebSquare 변환 확인: Provider----//
    if (frame.Provider("LoadingImg2") == null) {

	//----W-Craft WebSquare 변환 확인: CreateFrame----//
        frame.CreateFrame("LoadingImg2", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
    }
};



// 로딩이미지 숨기기
scwin.CloseWin2 = function(cnt, sval) {

	//----W-Craft WebSquare 변환 확인: Provider----//
    if (frame.Provider("LoadingImg2") != null) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//

	//----W-Craft WebSquare 변환 확인: Provider----//
        frame.Provider("LoadingImg2").CloseFrame();
        if (cnt == 0) $c.cm.ShowNoData(sval);
    }
};



// 부서코드, 사원코드 세팅
scwin.fn_SetCode = function() {
    dts_dep_cd.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + js_dep_cd;

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_dep_cd.Reset();

	//----W-Craft WebSquare 변환 확인: ExportData----//
    scwin.SetLog("dts_dep_cd", dts_dep_cd.ExportData(1, dts_dep_cd.CountRow, false));
    dts_emp_no.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + js_dep_cd;

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_emp_no.Reset();
};


// 보고서 조회
scwin.fn_OpenDisclosureSelect = function() {
    js_market = $c.stf.getObjectValue(rdo_mkt_id);

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    frame.CreateDialogFrame("DLG_ISUR_CD", "/dsclsrch/ULDSTF25002.gfm", "보고서 선택", 10, 10, 550, 770, "window");
    //if (getObjectValue(txb_form_cd) != "") {fn_GetVersion();}

};



// 해당기간, 서식코드의 버전별 건수 조회
scwin.fn_GetVersion = function() {
    if ($c.stf.getObjectValue(txb_form_cd) == "") {
        alert("[공시제목]을 선택하세요.");
        return;
    }
    /**********************************************************
     * - 2018.03.28 수정 :  버튼   클릭 안되게 처리                            *
     **********************************************************/
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select_d.gif";

	//----W-Craft WebSquare 변환 확인: all----//
    var url_all = "/NewDisclosureStatistics.do?method=getIntegratedVersion";

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_CD=" + $c.stf.getObjectValue(txb_form_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_VER=" + $c.stf.getObjectValue(cmb_form_ver);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SDATE=" + $c.stf.getObjectValue(edt_sdate);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&EDATE=" + $c.stf.getObjectValue(edt_edate);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&DEP_CD=" + $c.stf.getObjectValue(cmb_dep_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&EMP_NO=" + $c.stf.getObjectValue(cmb_emp_no);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&LIST_STAT_CD=" + $c.stf.getObjectValue(chb_list_stat_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&LAST_YN=" + $c.stf.getObjectValue(chk_last);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SUBCOM_DISCLS_EX_YN=" + $c.stf.getObjectValue(chk_branch);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&MKT_ID=" + $c.stf.getObjectValue(rdo_mkt_id);

	//----W-Craft WebSquare 변환 확인: all----//
    dts_form_ver.DataID = encodeURI(url_all);
    scwin.gDtsFormVerDuringTransaction = true;

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_form_ver.Reset();
    scwin.ShowWin2(grd_item);
};


// 상단그리드 다시 그리기
scwin.fn_StartPreview = function() {
    if ($c.stf.getObjectValue(txb_form_cd) == "") {
        alert("[공시제목]을 선택하세요.");
        return;
    }
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select_d.gif";
    dts_form_ver.CountRow;

	//----W-Craft WebSquare 변환 확인: ColumnString----//
    var vStr = dts_form_ver.ColumnString(cmb_form_ver.Index + 1, 2);
    if (scwin.fn_GetVersionCount(vStr) != '0') {
        // 건수가 존재하면 http request
        scwin.fn_GetHeaderItemsExcludeTuple();
    } else {
        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_search.setDisabled(true);
        btn_search.src = "../img/btn_select.gif";
    }
};




// 공시일자 10년 조회추가를 위한 공통함수 변형
scwin.fn_setFromToDate2 = function(pTp, pObjFrom, pObjTo) {
    var vFrom = "";
    var vTo = $c.stf.getObjectValue(pObjTo);
    if (vTo == '') {
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp == 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7);
    } else if (pTp == 2) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp == 3) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp == 4) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp == 5) {
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp == 6) {
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    } else if (pTp == 7) {
        vFrom = $c.ut.cGetMinusYear(vTo, 5);
    }
    $c.stf.setObjectValue(pObjFrom, vFrom);
    $c.stf.setObjectValue(pObjTo, vTo);
};


// 서식버전콤보박스 리스트 中  건수가 존재하는 서식버전으로 위치시키기
scwin.fn_LocateVer = function() {
    var isExist = false;
    var vStr = "";
    for (var i = 1; i < dts_form_ver.CountRow + 1; i++) {

	//----W-Craft WebSquare 변환 확인: ColumnString----//
        vStr = dts_form_ver.ColumnString(i, 2);
        if (scwin.fn_GetVersionCount(vStr) != 0) {
            isExist = true;
            if (i != 0) {
                cmb_form_ver.Index = i - 1;
            } else {
                cmb_form_ver.Index = i;
            }
            break;
        }
    }

    // 모든버전의 건수가 0일때
    if (isExist == false) {
        cmb_form_ver.Index = 0;
    }
};



// "5.01(100)"과 같은 서식버전문자열을 입력받아 괄호안에 숫자를 리턴
scwin.fn_GetVersionCount = function(vString) {
    var verCount = /\([0-9]+\)/g.exec(vString);
    verCount = verCount[0].replace("(", "").replace(")", "");
    return verCount;
};


// 서식항목 가져오기 (튜플 제외) 상단그리드헤더 그릴때 사용
scwin.fn_GetHeaderItemsExcludeTuple = function() {
    if ($c.stf.getObjectValue(txb_form_cd) == "") return;

    // 서식콤보 변경될때 메인그리드 내용 없앨지 남겨둘지
    //dts_main.ClearAll();


	//----W-Craft WebSquare 변환 확인: all----//
    var url_all = "/NewDisclosureStatistics.do?method=listIntegratedDsclItemsHeaderExcludeTuple";

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_CD=" + $c.stf.getObjectValue(txb_form_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_VER=" + $c.stf.getObjectValue(cmb_form_ver);

	//----W-Craft WebSquare 변환 확인: all----//
    dts_item_header_ex.DataID = encodeURI(url_all);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_item_header_ex.Reset();
};


// YYYYMMDD 문자열을 Date 객체로 변환
scwin.toDateObject = function(vDateStr) {
    var year = vDateStr.substr(0, 4);
    var month = vDateStr.substr(4, 2);
    var day = vDateStr.substr(6, 2);
    var hour = "00";
    var min = "00";
    return new Date(year, month, day, hour, min);
};


// 월수차이계산
scwin.getMonthInterval = function(vSDateStr, vEDateStr) {
    var date1 = scwin.toDateObject(vSDateStr);
    var date2 = scwin.toDateObject(vEDateStr);
    var years = date2.getFullYear() - date1.getFullYear();
    var months = date2.getMonth() - date1.getMonth();
    var days = date2.getDate() - date1.getDate();
    return (years * 12 + months + (days >= 0 ? 0 : -1));
};


// 사용자입력공시일자와 해당서식버전의 공시일자의 범위가 10년이 넘거나 건수가 2천건을 초과하는 경우
scwin.fn_ExpectHugeDataSize = function() {
    var userDateGap = scwin.getMonthInterval($c.stf.getObjectValue(edt_sdate), $c.stf.getObjectValue(edt_edate)); // 사용자입력 공시일자의 범위(월수)

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var formDateGap = scwin.getMonthInterval(dts_form_ver.NameValue(cmb_form_ver.Index + 1, "STRT_DD"), dts_form_ver.NameValue(cmb_form_ver.Index + 1, "END_DD")); // 서식버전의 공시일자 범위(월수)

	//----W-Craft WebSquare 변환 확인: ColumnString----//
    var countRow = scwin.fn_GetVersionCount(dts_form_ver.ColumnString(cmb_form_ver.Index + 1, 2));
    if ((userDateGap >= 120 && formDateGap >= 120) || countRow > 3000) {
        return true;
    } else {
        return false;
    }
};



// 하단그리드 메인조회
scwin.fn_SearchMain = function() {
    if (scwin.gDtsFormVerDuringTransaction) {
        alert("현재 버전별 접수건수를 가져오고 있습니다.  잠시기다려 주십시오.");
        return false;
    }

	//----W-Craft WebSquare 변환 확인: ColumnString----//
    if (dts_form_ver.ColumnString(1, 1) == "F") {
        alert("해당보고서의 버전건수가 없습니다.");
        return false;
    }
    if (dts_item_header_ex.CountRow <= 0) {
        alert("선택된 추출항목이 없습니다..");
        return false;
    }
    if (scwin.fn_ExpectHugeDataSize()) {
        alert("일자범위가 너무 길거나 해당 서식버전의 건수가 많아서 조회할 수 없습니다. 기간을 줄여주십시오.");
        return false;
    }

    /**********************************************************
     * - 2018.03.28 수정 : 주석처리, fn_GetVersion() 수행시 버튼   *
     *                                클릭 안되게 처리                                     *
     **********************************************************/
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    //btn_search.disabled = true;
    //btn_search.src = "../img/btn_select_d.gif";


    scwin.ShowWin2(grd_main);
    scwin.gSDate = new Date();
    scwin.gSTimer = scwin.gSDate.getTime();
    panel_msg.innerHTML = "";
    panel_page.innerHTML = "";
    scwin.fn_GetHeaderItemsIncludeTuple();
};


// 서식항목 가져오기 (튜플 포함) 하단그리드헤더 그릴때 사용
scwin.fn_GetHeaderItemsIncludeTuple = function() {
    if ($c.stf.getObjectValue(txb_form_cd) == "") return;

    // 조회시 메인그리드 내용 없앨지 남겨둘지
    //dts_main.ClearAll();


	//----W-Craft WebSquare 변환 확인: all----//
    var url_all = "/NewDisclosureStatistics.do?method=listIntegratedDsclItemsHeaderIncludeTuple";

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_CD=" + $c.stf.getObjectValue(txb_form_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&FORM_VER=" + $c.stf.getObjectValue(cmb_form_ver);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SDATE=" + $c.stf.getObjectValue(edt_sdate);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&EDATE=" + $c.stf.getObjectValue(edt_edate);

	//----W-Craft WebSquare 변환 확인: NameValue----//

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SFDATE=" + dts_form_ver.NameValue(cmb_form_ver.Index + 1, "STRT_DD");

	//----W-Craft WebSquare 변환 확인: NameValue----//

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&EFDATE=" + dts_form_ver.NameValue(cmb_form_ver.Index + 1, "END_DD");

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&DEP_CD=" + $c.stf.getObjectValue(cmb_dep_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&EMP_NO=" + $c.stf.getObjectValue(cmb_emp_no);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&LIST_STAT_CD=" + $c.stf.getObjectValue(chb_list_stat_cd);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&LAST_YN=" + $c.stf.getObjectValue(chk_last);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&MKT_ID=" + $c.stf.getObjectValue(rdo_mkt_id);

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SCREN_ID=" + scwin.vScrenID;

	//----W-Craft WebSquare 변환 확인: all----//
    url_all += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

	//----W-Craft WebSquare 변환 확인: all----//
    dts_item_header_in.DataID = encodeURI(url_all);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_item_header_in.Reset();
};


// 상단그리드에 체크된 항목 구하기
scwin.fn_GetSelectedItems = function() {
    var selectedItems = "";
    for (var j = 1; j < dts_item_dummy.CountColumn + 1; j++) {

	//----W-Craft WebSquare 변환 확인: ColumnID----//
        var itemValue = dts_item_dummy.ColumnID(j);

	//----W-Craft WebSquare 변환 확인: NameString----//
        if ("T" == dts_item_dummy.NameString(1, itemValue)) {
            selectedItems += itemValue + "|";
        }
    }
    scwin.SetLog("선택항목", selectedItems);
    return selectedItems;
};


