scwin.dts_item_header_in_OnLoadCompleted = function(rowcount) {
    // 튜플항목을 모두 받아온 후에 메인 검색 시작
    if (scwin.fn_FindUncheckItem()) {
        for (var i = 1; i < dts_item_dummy + 1; i++) {

	//----W-Craft WebSquare 변환 확인: ColumnID----//
            var colid = dts_item_dummy.ColumnID(i);
            grd_main.Redraw = false;
            scwin.fn_CheckDisclsItems(colid);
            grd_main.Redraw = true;
        }
    } else {
        scwin.fn_SetMultiHeader(grd_main, dts_item_header_in);
    }
    var FORM_CD = $c.stf.getObjectValue(txb_form_cd);
    if (FORM_CD == "") {
        alert("[공시]를 선택하세요.");
        return;
    }
    var SDATE = $c.stf.getObjectValue(edt_sdate);
    var EDATE = $c.stf.getObjectValue(edt_edate);
    if (SDATE == "") {
        alert("[공시일자 - 시작일]을 입력하세요.");
        return;
    }
    if (EDATE == "") {
        alert("[공시일자 - 종료일]을 입력하세요.");
        return;
    }
    var selectedItems = scwin.fn_GetSelectedItems();
    if ("" == selectedItems) {
        alert("조회하고자 하는 항목을 선택하세요.");
        return;
    }
    var url = "/NewDisclosureStatistics.do?method=listIntegratedDisclosureStatistics";
    url += "&FORM_CD=" + FORM_CD;
    url += "&FORM_VER=" + $c.stf.getObjectValue(cmb_form_ver);
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;

	//----W-Craft WebSquare 변환 확인: NameValue----//
    url += "&SFDATE=" + dts_form_ver.NameValue(cmb_form_ver.Index + 1, "STRT_DD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    url += "&EFDATE=" + dts_form_ver.NameValue(cmb_form_ver.Index + 1, "END_DD");
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_dep_cd);
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_emp_no);
    url += "&LIST_STAT_CD=" + $c.stf.getObjectValue(chb_list_stat_cd);
    url += "&LAST_YN=" + $c.stf.getObjectValue(chk_last);
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_mkt_id);
    url += "&SUBCOM_DISCLS_EX_YN=" + $c.stf.getObjectValue(chk_branch);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.SetLog("mainsearch request", url);
    dts_main.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_main.Reset();
};
scwin.dts_main_OnLoadCompleted = function(rowcount) {
    //alert(dts_main.ExportData(1,1,false));
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    var dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    var min = Math.round(dispTimer / 60, 2);
    var sec = Math.round(dispTimer % 60);
    var vCntMsg;

	//----W-Craft WebSquare 변환 확인: ColumnString----//
    if (rowcount != scwin.fn_GetVersionCount(dts_form_ver.ColumnString(cmb_form_ver.Index + 1, 2))) {
        vcolor = "#ff0000";
        vCntMsg = $c.stf.FormatNumberEx(rowcount) + '(접수건과 추출건 불일치)';
    } else {
        vcolor = "#5c8be0";
        vCntMsg = $c.stf.FormatNumberEx(rowcount);
    }
    var vTotalArea = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>추출건수: </span><span style='font-size__9pt; font-family:굴림; color:" + vcolor + "; font-weight:bold'>" + vCntMsg + "</span>";
    panel_page.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
    var dtsSize = dts_main.CountColumn * 3;
    for (var j = 1; j < dts_main.CountColumn + 1; j++) {

	//----W-Craft WebSquare 변환 확인: ColumnSize----//
        dtsSize = dtsSize + dts_main.ColumnSize(j);
    }
    dtsSize = dtsSize * rowcount;
    var posV = Math.pow(10, 2);
    scwin.gDtsSize = Math.round(dtsSize / 1024 / 1024 * posV) / posV;
    panel_size.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap><span style='font-size__9pt; font-family:굴림; color:#FFFFFF; font-weight:bold'>패킷 크기 : " + scwin.gDtsSize + "MBytes, 펫치 건수 : " + $c.stf.FormatNumberEx(rowcount * dts_main.CountColumn) + " 건</span></td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
    $c.stf.PanelMsg(panel_msg, "처리시간 : " + min + " 분 " + sec + "초");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(true);
    btn_search.src = "../img/btn_select.gif";
    scwin.CloseWin2(rowcount, grd_main);
};

