                if (data == 67) {

	//----W-Craft WebSquare 변환 확인: setData----//

	//----W-Craft WebSquare 변환 확인: NameString----//
                    window.clipboardData.setData("TEXT", dts_main.NameString(dts_main.RowPosition, "ACPT_NO"));
                }
            };

            function btn_getversion_onclick(e) {
                if ($c.stf.getObjectValue(txb_form_cd) != "") {
                    scwin.fn_GetVersion();
                }
            };

            function btn_preview_onclick(e) {
                scwin.fn_StartPreview();
            };

            function btn_info_onclick(e) {
                var url = "/dsclsrch/HELP_DSCLEXTRCINFO.html";
                var winTitle = "공시추출통계 도움말";

	//----W-Craft WebSquare 변환 확인: CreateFrame----//
                frame.CreateFrame("HELP_KEY", url, winTitle, 10, 10, 1160, 720, "window", 0, 0, true);
            };

            function dts_form_ver_OnLoadError() {
                scwin.gDtsFormVerDuringTransaction = false;
            };

            function dts_form_ver_OnLoadProcess(rowcount) {
                scwin.gDtsFormVerDuringTransaction = true;
            };

            function gform_onload() {
                $c.libRoundPanel.PanelToGroupBox(pnl_main);
                scwin.fn_SetCode();
                scwin.fn_Init();
                $c.cm.fn_com_isur(txb_isur_cd, txb_com_nm);
                $c.stf.setObjectValue(edt_sdate, $c.ut.calcMonth($c.ut.cGetToday2(), -3));
                $c.stf.setObjectValue(edt_edate, $c.ut.cGetToday2());
            };

            function Grd_com_isur_OnKeyPress(kcode) {
                if (kcode == '13') {
                    $c.cm.fn_com_Confirm_set();
                }
            };

            function Grd_com_isur_OnDblClick(row, colid) {
                $c.cm.fn_com_Confirm_set();
            };

            function Grd_com_isur_OnClick(row, colid) {
                Grd_com_isur.style.display = "";
            };


	//----W-Craft WebSquare 변환 확인: Focus----//
            function Grd_com_isur_OnSetFocus() {

	//----W-Craft WebSquare 변환 확인: Focus----//
                stFocusGrid = true;
            };


	//----W-Craft WebSquare 변환 확인: Focus----//
            function Grd_com_isur_OnKillFocus() {

	//----W-Craft WebSquare 변환 확인: Focus----//
                stFocusGrid = false;
                Grd_com_isur.style.display = "none";
            };


	//----W-Craft WebSquare 변환 확인: Filter----//
            function MxDataSet_com_isur_OnFilter(row) {
                if (skw != "" && foColum == "1") {

	//----W-Craft WebSquare 변환 확인: NameString----//
                    f1 = MxDataSet_com_isur.NameString(row, "COM_ABBRV");

	//----W-Craft WebSquare 변환 확인: NameString----//
                    f2 = MxDataSet_com_isur.NameString(row, "OLD_COM_ABBRV");
                    if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

                    else return false;
                } else {
                    return true;
                }
            };
        };
    };
};
